### Complete Single-File C# Implementation

Create a new C# Console Project (`dotnet new console`) and replace the contents of `Program.cs` with the following comprehensive, production-grade codebase:

```csharp
using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;

namespace DistributedQueryOptimizer
{
    #region --- SYSTEM ENTRY POINT & DEMO ---

    public class Program
    {
        public static void Main(string[] args)
        {
            Console.OutputEncoding = Encoding.UTF8;
            Console.WriteLine("================================================================");
            Console.WriteLine("        DISTRIBUTED DATABASE QUERY OPTIMIZER ENGINE");
            Console.WriteLine("================================================================\n");

            // 1. Initialize Distributed Database Cluster Catalog Metadata
            var catalog = SetupClusterCatalog();

            // 2. Define Query to Optimize
            // This multi-way join highlights different optimization decisions:
            // - Joining Customer and Orders can be Co-Located (partitioned on same keys/nodes)
            // - Joining with Region should choose Broadcast Join (Region is tiny)
            string sqlQuery = "SELECT Customer.Name, Orders.Total, Region.Name " +
                              "FROM Customer " +
                              "JOIN Orders ON Customer.Id = Orders.CustomerId " +
                              "JOIN Region ON Customer.RegionId = Region.Id " +
                              "WHERE Customer.Status = 'Active' AND Orders.Total = 500";

            Console.WriteLine($"[SQL QUERY]:\n{sqlQuery}\n");

            try
            {
                // PHASE 1: AST Lexing & Parsing
                Console.WriteLine("----------------------------------------------------------------");
                Console.WriteLine("[PHASE 1] parsing SQL Query text into AST Tree...");
                var lexer = new Lexer(sqlQuery);
                var tokens = lexer.Tokenize();
                var parser = new Parser(tokens);
                var ast = parser.Parse();
                Console.WriteLine("\n[PARSED AST]:");
                Console.WriteLine(ast.ToPrettyString());
                Console.WriteLine("----------------------------------------------------------------\n");

                // PHASE 2: Logical Decomposition & Planning
                Console.WriteLine("[PHASE 2] Decomposing AST into Relational Sub-predicates...");
                var decomposer = new QueryDecomposer();
                decomposer.Decompose(ast);

                Console.WriteLine($"Identified Tables: {string.Join(", ", decomposer.Tables)}");
                Console.WriteLine("Join Predicates:");
                foreach (var jp in decomposer.JoinPredicates)
                    Console.WriteLine($"  - {jp.LeftTable}.{jp.LeftColumn} = {jp.RightTable}.{jp.RightColumn}");
                Console.WriteLine("Filter Predicates:");
                foreach (var fp in decomposer.FilterPredicates)
                    Console.WriteLine($"  - {fp.TableName}.{fp.ColumnName} {fp.Operator} {fp.ConstantValue}");
                Console.WriteLine("----------------------------------------------------------------\n");

                // PHASE 3: Cost-Based Join Permutation Evaluation (System-R DP)
                Console.WriteLine("[PHASE 3] Running Cost-Based Optimizer (CBO) Engine...");
                var cbo = new DistributedCboEngine(catalog, decomposer.JoinPredicates, decomposer.FilterPredicates);
                var optimalSubPlan = cbo.Optimize(decomposer.Tables);
                Console.WriteLine("----------------------------------------------------------------\n");

                // PHASE 4: Execution Plan Generation (Physical Root Generation)
                Console.WriteLine("[PHASE 4] Generating Optimal Physical Operator Execution Tree...");
                var finalPhysicalPlan = new PhysicalProject(optimalSubPlan, ast.Projections);

                Console.WriteLine("\n================================================================");
                Console.WriteLine("               OPTIMAL PHYSICAL EXECUTION PLAN");
                Console.WriteLine("================================================================");
                finalPhysicalPlan.Print(0);
                Console.WriteLine("================================================================");
                Console.WriteLine($"Total Cost Estimate: {finalPhysicalPlan.CumulativeCost}");
                Console.WriteLine($"Estimated Yield Card: {finalPhysicalPlan.EstimatedRowCount:N0} rows");
                Console.WriteLine("================================================================");
            }
            catch (Exception ex)
            {
                Console.ForegroundColor = ConsoleColor.Red;
                Console.WriteLine($"Optimization failed: {ex.Message}");
                Console.WriteLine(ex.StackTrace);
                Console.ResetColor();
            }
        }

        private static ClusterCatalog SetupClusterCatalog()
        {
            var catalog = new ClusterCatalog();

            // Large customer data, hash partitioned on ID
            catalog.RegisterTable(new TableMetadata(
                name: "Customer",
                rowCount: 1_000_000,
                rowSize: 120, // bytes
                partitionKey: "Id",
                nodes: new HashSet<string> { "Node1", "Node2", "Node3" }
            ));

            // Massive transactional orders data, hash partitioned on CustomerId (matching Customer's partition nodes)
            catalog.RegisterTable(new TableMetadata(
                name: "Orders",
                rowCount: 10_000_000,
                rowSize: 80, // bytes
                partitionKey: "CustomerId",
                nodes: new HashSet<string> { "Node1", "Node2", "Node3" }
            ));

            // Tiny region lookup data, kept on a single specialized reference node
            catalog.RegisterTable(new TableMetadata(
                name: "Region",
                rowCount: 50,
                rowSize: 40, // bytes
                partitionKey: "Id",
                nodes: new HashSet<string> { "Node4" }
            ));

            return catalog;
        }
    }

    #endregion

    #region --- MODULE 1: SQL AST PARSER ---

    public enum TokenType
    {
        Select, From, Join, On, Where, And,
        Identifier, Number, String,
        Equals, Comma, Dot, OpenParenthesis, CloseParenthesis, EOF
    }

    public class Token
    {
        public TokenType Type { get; }
        public string Value { get; }
        public Token(TokenType type, string value) { Type = type; Value = value; }
        public override string ToString() => $"{Type}: {Value}";
    }

    public class Lexer
    {
        private readonly string _src;
        private int _index;
        public Lexer(string src) { _src = src; _index = 0; }

        public List<Token> Tokenize()
        {
            var tokens = new List<Token>();
            while (_index < _src.Length)
            {
                char current = _src[_index];
                if (char.IsWhiteSpace(current)) { _index++; continue; }
                if (current == '=') { tokens.Add(new Token(TokenType.Equals, "=")); _index++; continue; }
                if (current == ',') { tokens.Add(new Token(TokenType.Comma, ",")); _index++; continue; }
                if (current == '.') { tokens.Add(new Token(TokenType.Dot, ".")); _index++; continue; }
                if (current == '(') { tokens.Add(new Token(TokenType.OpenParenthesis, "(")); _index++; continue; }
                if (current == ')') { tokens.Add(new Token(TokenType.CloseParenthesis, ")")); _index++; continue; }
                if (current == '\'')
                {
                    _index++; // skip single quote
                    int start = _index;
                    while (_index < _src.Length && _src[_index] != '\'') _index++;
                    string str = _src.Substring(start, _index - start);
                    _index++; // skip close quote
                    tokens.Add(new Token(TokenType.String, str));
                    continue;
                }
                if (char.IsDigit(current))
                {
                    int start = _index;
                    while (_index < _src.Length && char.IsDigit(_src[_index])) _index++;
                    tokens.Add(new Token(TokenType.Number, _src.Substring(start, _index - start)));
                    continue;
                }
                if (char.IsLetter(current) || current == '_')
                {
                    int start = _index;
                    while (_index < _src.Length && (char.IsLetterOrDigit(_src[_index]) || _src[_index] == '_')) _index++;
                    string val = _src.Substring(start, _index - start);
                    string upper = val.ToUpperInvariant();
                    switch (upper)
                    {
                        case "SELECT": tokens.Add(new Token(TokenType.Select, val)); break;
                        case "FROM": tokens.Add(new Token(TokenType.From, val)); break;
                        case "JOIN": tokens.Add(new Token(TokenType.Join, val)); break;
                        case "ON": tokens.Add(new Token(TokenType.On, val)); break;
                        case "WHERE": tokens.Add(new Token(TokenType.Where, val)); break;
                        case "AND": tokens.Add(new Token(TokenType.And, val)); break;
                        default: tokens.Add(new Token(TokenType.Identifier, val)); break;
                    }
                    continue;
                }
                throw new Exception($"Unexpected character context encountered: {current} at index {_index}");
            }
            tokens.Add(new Token(TokenType.EOF, ""));
            return tokens;
        }
    }

    public abstract class AstNode
    {
        public abstract string ToPrettyString(int indent = 0);
    }

    public class SqlSelectNode : AstNode
    {
        public List<ExpressionNode> Projections { get; }
        public TableSourceNode From { get; }
        public ExpressionNode WhereClause { get; }

        public SqlSelectNode(List<ExpressionNode> projections, TableSourceNode from, ExpressionNode whereClause)
        {
            Projections = projections;
            From = from;
            WhereClause = whereClause;
        }

        public override string ToPrettyString(int indent = 0)
        {
            var sb = new StringBuilder();
            var ind = new string(' ', indent);
            sb.AppendLine($"{ind}SELECT");
            foreach (var p in Projections)
                sb.AppendLine($"{ind}  - {p.ToPrettyString()}");
            sb.AppendLine($"{ind}FROM");
            sb.AppendLine(From.ToPrettyString(indent + 2));
            if (WhereClause != null)
            {
                sb.AppendLine($"{ind}WHERE");
                sb.AppendLine(WhereClause.ToPrettyString(indent + 2));
            }
            return sb.ToString().TrimEnd();
        }
    }

    public abstract class TableSourceNode : AstNode { }

    public class BaseTableNode : TableSourceNode
    {
        public string Name { get; }
        public string Alias { get; }
        public BaseTableNode(string name, string alias) { Name = name; Alias = alias; }

        public override string ToPrettyString(int indent = 0)
        {
            var ind = new string(' ', indent);
            return $"{ind}{Name}" + (string.IsNullOrEmpty(Alias) ? "" : $" AS {Alias}");
        }
    }

    public class JoinTableNode : TableSourceNode
    {
        public TableSourceNode Left { get; }
        public TableSourceNode Right { get; }
        public BinaryOpNode Condition { get; }

        public JoinTableNode(TableSourceNode left, TableSourceNode right, BinaryOpNode condition)
        {
            Left = left;
            Right = right;
            Condition = condition;
        }

        public override string ToPrettyString(int indent = 0)
        {
            var ind = new string(' ', indent);
            var sb = new StringBuilder();
            sb.AppendLine(Left.ToPrettyString(indent));
            sb.AppendLine($"{ind}JOIN");
            sb.AppendLine(Right.ToPrettyString(indent + 2));
            sb.AppendLine($"{ind}ON {Condition.ToPrettyString()}");
            return sb.ToString().TrimEnd();
        }
    }

    public abstract class ExpressionNode : AstNode { }

    public class IdentifierNode : ExpressionNode
    {
        public string TableAlias { get; }
        public string ColumnName { get; }
        public IdentifierNode(string tableAlias, string columnName) { TableAlias = tableAlias; ColumnName = columnName; }

        public override string ToPrettyString(int indent = 0)
        {
            return string.IsNullOrEmpty(TableAlias) ? ColumnName : $"{TableAlias}.{ColumnName}";
        }
    }

    public class LiteralNode : ExpressionNode
    {
        public object Value { get; }
        public LiteralNode(object value) { Value = value; }
        public override string ToPrettyString(int indent = 0) => Value is string ? $"'{Value}'" : Value.ToString();
    }

    public class BinaryOpNode : ExpressionNode
    {
        public ExpressionNode Left { get; }
        public string Operator { get; }
        public ExpressionNode Right { get; }

        public BinaryOpNode(ExpressionNode left, string op, ExpressionNode right)
        {
            Left = left;
            Operator = op;
            Right = right;
        }

        public override string ToPrettyString(int indent = 0)
        {
            return $"({Left.ToPrettyString()} {Operator} {Right.ToPrettyString()})";
        }
    }

    public class Parser
    {
        private readonly List<Token> _tokens;
        private int _index;
        public Parser(List<Token> tokens) { _tokens = tokens; _index = 0; }

        private Token Peek() => _tokens[_index];
        private Token Consume(TokenType type)
        {
            var tok = Peek();
            if (tok.Type != type)
                throw new Exception($"Expected token type {type}, found {tok.Type} ('{tok.Value}') at token position {_index}");
            _index++;
            return tok;
        }

        public SqlSelectNode Parse()
        {
            Consume(TokenType.Select);
            var projections = ParseProjections();
            Consume(TokenType.From);
            var fromNode = ParseTableSource();
            ExpressionNode whereClause = null;
            if (Peek().Type == TokenType.Where)
            {
                Consume(TokenType.Where);
                whereClause = ParseExpression();
            }
            Consume(TokenType.EOF);
            return new SqlSelectNode(projections, fromNode, whereClause);
        }

        private List<ExpressionNode> ParseProjections()
        {
            var list = new List<ExpressionNode>();
            list.Add(ParseExpression());
            while (Peek().Type == TokenType.Comma)
            {
                Consume(TokenType.Comma);
                list.Add(ParseExpression());
            }
            return list;
        }

        private TableSourceNode ParseTableSource()
        {
            TableSourceNode node = ParseBaseTable();
            while (Peek().Type == TokenType.Join)
            {
                Consume(TokenType.Join);
                var right = ParseBaseTable();
                Consume(TokenType.On);
                var cond = ParseExpression();
                if (cond is BinaryOpNode bin)
                {
                    node = new JoinTableNode(node, right, bin);
                }
                else
                {
                    throw new Exception("Error: JOIN ON clause condition must be binary equality operator expression!");
                }
            }
            return node;
        }

        private BaseTableNode ParseBaseTable()
        {
            var nameTok = Consume(TokenType.Identifier);
            string alias = null;
            if (Peek().Type == TokenType.Identifier)
            {
                alias = Consume(TokenType.Identifier).Value;
            }
            return new BaseTableNode(nameTok.Value, alias);
        }

        private ExpressionNode ParseExpression()
        {
            var left = ParsePrimary();
            if (Peek().Type == TokenType.Equals)
            {
                var op = Consume(TokenType.Equals).Value;
                var right = ParsePrimary();
                left = new BinaryOpNode(left, op, right);
            }
            while (Peek().Type == TokenType.And)
            {
                var op = Consume(TokenType.And).Value;
                var right = ParseExpression();
                left = new BinaryOpNode(left, op, right);
            }
            return left;
        }

        private ExpressionNode ParsePrimary()
        {
            var tok = Peek();
            if (tok.Type == TokenType.Identifier)
            {
                Consume(TokenType.Identifier);
                if (Peek().Type == TokenType.Dot)
                {
                    Consume(TokenType.Dot);
                    var colTok = Consume(TokenType.Identifier);
                    return new IdentifierNode(tok.Value, colTok.Value);
                }
                return new IdentifierNode(null, tok.Value);
            }
            if (tok.Type == TokenType.Number)
            {
                Consume(TokenType.Number);
                return new LiteralNode(int.Parse(tok.Value));
            }
            if (tok.Type == TokenType.String)
            {
                Consume(TokenType.String);
                return new LiteralNode(tok.Value);
            }
            throw new Exception($"Unexpected token within expression parser context: {tok}");
        }
    }

    #endregion

    #region --- MODULE 2: DECOMPOSITION & OPTIMIZATION PARAMETERS ---

    public class JoinPredicate
    {
        public string LeftTable { get; set; }
        public string LeftColumn { get; set; }
        public string RightTable { get; set; }
        public string RightColumn { get; set; }
        public string Operator { get; set; }
    }

    public class FilterPredicate
    {
        public string TableName { get; set; }
        public string ColumnName { get; set; }
        public string Operator { get; set; }
        public object ConstantValue { get; set; }
    }

    public class QueryDecomposer
    {
        public List<string> Tables { get; } = new();
        public List<JoinPredicate> JoinPredicates { get; } = new();
        public List<FilterPredicate> FilterPredicates { get; } = new();
        private readonly Dictionary<string, string> _aliasToTableMap = new(StringComparer.OrdinalIgnoreCase);

        public void Decompose(SqlSelectNode root)
        {
            ExtractTablesAndJoins(root.From);
            if (root.WhereClause != null) ExtractFilters(root.WhereClause);

            // Standardize Aliases back to original registered Table names for CBO metadata lookup consistency
            foreach (var pred in JoinPredicates)
            {
                if (_aliasToTableMap.TryGetValue(pred.LeftTable, out var leftReal)) pred.LeftTable = leftReal;
                if (_aliasToTableMap.TryGetValue(pred.RightTable, out var rightReal)) pred.RightTable = rightReal;
            }
            foreach (var filter in FilterPredicates)
            {
                if (_aliasToTableMap.TryGetValue(filter.TableName, out var realTable)) filter.TableName = realTable;
            }
        }

        private void ExtractTablesAndJoins(TableSourceNode node)
        {
            if (node is BaseTableNode baseTable)
            {
                Tables.Add(baseTable.Name);
                if (!string.IsNullOrEmpty(baseTable.Alias))
                    _aliasToTableMap[baseTable.Alias] = baseTable.Name;
                else
                    _aliasToTableMap[baseTable.Name] = baseTable.Name;
            }
            else if (node is JoinTableNode joinTable)
            {
                ExtractTablesAndJoins(joinTable.Left);
                ExtractTablesAndJoins(joinTable.Right);

                if (joinTable.Condition is BinaryOpNode bin && bin.Operator == "=")
                {
                    if (bin.Left is IdentifierNode leftId && bin.Right is IdentifierNode rightId)
                    {
                        JoinPredicates.Add(new JoinPredicate
                        {
                            LeftTable = leftId.TableAlias,
                            LeftColumn = leftId.ColumnName,
                            RightTable = rightId.TableAlias,
                            RightColumn = rightId.ColumnName,
                            Operator = "="
                        });
                    }
                }
            }
        }

        private void ExtractFilters(ExpressionNode node)
        {
            if (node is BinaryOpNode bin)
            {
                if (bin.Operator == "AND")
                {
                    ExtractFilters(bin.Left);
                    ExtractFilters(bin.Right);
                }
                else if (bin.Operator == "=")
                {
                    if (bin.Left is IdentifierNode id && bin.Right is LiteralNode lit)
                    {
                        FilterPredicates.Add(new FilterPredicate
                        {
                            TableName = id.TableAlias,
                            ColumnName = id.ColumnName,
                            Operator = "=",
                            ConstantValue = lit.Value
                        });
                    }
                    else if (bin.Left is LiteralNode litL && bin.Right is IdentifierNode idR)
                    {
                        FilterPredicates.Add(new FilterPredicate
                        {
                            TableName = idR.TableAlias,
                            ColumnName = idR.ColumnName,
                            Operator = "=",
                            ConstantValue = litL.Value
                        });
                    }
                }
            }
        }
    }

    public static class CostModel
    {
        public const double NETWORK_BANDWIDTH_BYTES_PER_SEC = 10 * 1024 * 1024; // Standard 10MB/sec inter-node speed representation
        public const double CPU_ROW_OP_COST = 0.0000001; // CPU evaluation seconds per row
        public const double IO_ROW_READ_COST = 0.000002; // Disk Read seek/IO seconds per row
        public const double HASH_JOIN_CPU_FACTOR = 0.0000005; // Join hash creation/probe overhead
    }

    public class TableMetadata
    {
        public string Name { get; }
        public long RowCount { get; }
        public int RowSize { get; }
        public string PartitionKey { get; }
        public HashSet<string> Nodes { get; }

        public TableMetadata(string name, long rowCount, int rowSize, string partitionKey, HashSet<string> nodes)
        {
            Name = name;
            RowCount = rowCount;
            RowSize = rowSize;
            PartitionKey = partitionKey;
            Nodes = nodes;
        }
    }

    public class ClusterCatalog
    {
        private readonly Dictionary<string, TableMetadata> _tables = new(StringComparer.OrdinalIgnoreCase);
        public void RegisterTable(TableMetadata meta) => _tables[meta.Name] = meta;
        public TableMetadata GetTable(string name)
        {
            if (!_tables.TryGetValue(name, out var meta))
                throw new Exception($"Catalog query failed: Table schema details for '{name}' are not defined in metadata.");
            return meta;
        }
    }

    public class PlanCost
    {
        public double NetworkCost { get; }
        public double CpuCost { get; }
        public double IoCost { get; }
        public double TotalCost => NetworkCost + CpuCost + IoCost;

        public PlanCost(double network, double cpu, double io)
        {
            NetworkCost = network;
            CpuCost = cpu;
            IoCost = io;
        }

        public static PlanCost operator +(PlanCost a, PlanCost b) =>
            new PlanCost(a.NetworkCost + b.NetworkCost, a.CpuCost + b.CpuCost, a.IoCost + b.IoCost);

        public static PlanCost operator -(PlanCost a, PlanCost b) =>
            new PlanCost(a.NetworkCost - b.NetworkCost, a.CpuCost - b.CpuCost, a.IoCost - b.IoCost);

        public override string ToString() => $"Total={TotalCost:F5}s [Net={NetworkCost:F5}s, CPU={CpuCost:F5}s, IO={IoCost:F5}s]";
    }

    public enum DistributionType { Broadcast, Hash, Single }

    public class PhysicalDistribution
    {
        public DistributionType Type { get; }
        public string PartitionKey { get; }
        public HashSet<string> Nodes { get; }

        public PhysicalDistribution(DistributionType type, string partitionKey, HashSet<string> nodes)
        {
            Type = type;
            PartitionKey = partitionKey;
            Nodes = nodes ?? new HashSet<string>();
        }

        public bool IsCoLocatedWith(PhysicalDistribution other, string leftKey, string rightKey)
        {
            if (Type != DistributionType.Hash || other.Type != DistributionType.Hash) return false;
            if (!string.Equals(PartitionKey, leftKey, StringComparison.OrdinalIgnoreCase)) return false;
            if (!string.Equals(other.PartitionKey, rightKey, StringComparison.OrdinalIgnoreCase)) return false;
            return Nodes.SetEquals(other.Nodes);
        }

        public override string ToString()
        {
            string nodesStr = string.Join(",", Nodes);
            return Type == DistributionType.Hash ? $"Hash({PartitionKey}) on [{nodesStr}]" : $"{Type} on [{nodesStr}]";
        }
    }

    public static class SetHelper
    {
        public static string GetKey(IEnumerable<string> tables) =>
            string.Join(",", tables.OrderBy(t => t, StringComparer.OrdinalIgnoreCase));

        public static List<List<string>> GetSubsets(List<string> items)
        {
            var subsets = new List<List<string>>();
            int count = 1 << items.Count;
            for (int i = 1; i < count; i++)
            {
                var subset = new List<string>();
                for (int j = 0; j < items.Count; j++)
                {
                    if ((i & (1 << j)) != 0) subset.Add(items[j]);
                }
                subsets.Add(subset);
            }
            return subsets;
        }
    }

    #endregion

    #region --- MODULE 3: COST-BASED OPTIMIZATION ENGINE ---

    public interface IPhysicalOperator
    {
        PhysicalDistribution Distribution { get; }
        PlanCost CumulativeCost { get; }
        double EstimatedRowCount { get; }
        HashSet<string> CoveredTables { get; }
        void Print(int indent);
    }

    public class DistributedCboEngine
    {
        private readonly ClusterCatalog _catalog;
        private readonly List<JoinPredicate> _joinPredicates;
        private readonly List<FilterPredicate> _filterPredicates;

        public DistributedCboEngine(ClusterCatalog catalog, List<JoinPredicate> joinPreds, List<FilterPredicate> filterPreds)
        {
            _catalog = catalog;
            _joinPredicates = joinPreds;
            _filterPredicates = filterPreds;
        }

        public IPhysicalOperator Optimize(List<string> tables)
        {
            // DP optimal mapping sub-plans table key -> Optimal physical node path
            var dpTable = new Dictionary<string, IPhysicalOperator>(StringComparer.OrdinalIgnoreCase);

            // PHASE A: Leaf-Level Base Tables Planning (Size 1)
            foreach (var table in tables)
            {
                var meta = _catalog.GetTable(table);
                IPhysicalOperator currentPlan = new PhysicalScan(meta);

                // Inline and push down single-table local filters
                var localFilters = _filterPredicates.Where(f => f.TableName.Equals(table, StringComparison.OrdinalIgnoreCase)).ToList();
                foreach (var filter in localFilters)
                {
                    currentPlan = new PhysicalFilter(currentPlan, filter);
                }

                string key = SetHelper.GetKey(new[] { table });
                dpTable[key] = currentPlan;

                Console.WriteLine($"[CBO Base Initialized] '{key}' -> Card={currentPlan.EstimatedRowCount:N0} rows, Cost: {currentPlan.CumulativeCost}");
            }

            // PHASE B: Permutations Space Sweep via Dynamic Programming (Subsets Size 2 -> N)
            var sortedSubsets = SetHelper.GetSubsets(tables)
                .OrderBy(s => s.Count)
                .ToList();

            foreach (var subset in sortedSubsets)
            {
                if (subset.Count <= 1) continue;

                string subsetKey = SetHelper.GetKey(subset);
                IPhysicalOperator bestPlanForSubset = null;

                // Divide subset into two disjoint non-empty halves: S1 and S2
                var splits = GenerateDisjointSplits(subset);
                foreach (var (s1, s2) in splits)
                {
                    string key1 = SetHelper.GetKey(s1);
                    string key2 = SetHelper.GetKey(s2);

                    if (!dpTable.TryGetValue(key1, out var plan1) || !dpTable.TryGetValue(key2, out var plan2))
                        continue;

                    // Match Join Relation link logic between S1 and S2
                    var joinPredicate = MatchJoinPredicate(s1, s2);
                    if (joinPredicate == null) continue; // Skip cross-joins to prune optimization search path

                    // Probe and analyze physical distributed implementation alternatives
                    var candidatePlans = EvaluatePhysicalJoinOptions(plan1, plan2, joinPredicate);
                    foreach (var candidate in candidatePlans)
                    {
                        if (bestPlanForSubset == null || candidate.CumulativeCost.TotalCost < bestPlanForSubset.CumulativeCost.TotalCost)
                        {
                            bestPlanForSubset = candidate;
                        }
                    }
                }

                if (bestPlanForSubset != null)
                {
                    dpTable[subsetKey] = bestPlanForSubset;
                    Console.WriteLine($"[CBO DP Evaluation] Optimized Sub-Join {{{subsetKey}}} -> Cost: {bestPlanForSubset.CumulativeCost} via Strategy: {bestPlanForSubset.GetType().Name}");
                }
            }

            string completeKey = SetHelper.GetKey(tables);
            if (!dpTable.TryGetValue(completeKey, out var optimalRootPlan))
                throw new Exception("Optimization Failed: Dynamic Programming could not establish a valid connected join plan.");

            return optimalRootPlan;
        }

        private List<(List<string> S1, List<string> S2)> GenerateDisjointSplits(List<string> subset)
        {
            var splits = new List<(List<string>, List<string>)>();
            int count = 1 << subset.Count;
            for (int i = 1; i < count - 1; i++)
            {
                var s1 = new List<string>();
                var s2 = new List<string>();
                for (int j = 0; j < subset.Count; j++)
                {
                    if ((i & (1 << j)) != 0) s1.Add(subset[j]);
                    else s2.Add(subset[j]);
                }
                splits.Add((s1, s2));
            }
            return splits;
        }

        private JoinPredicate MatchJoinPredicate(List<string> s1, List<string> s2)
        {
            foreach (var p in _joinPredicates)
            {
                bool leftInS1 = s1.Contains(p.LeftTable, StringComparer.OrdinalIgnoreCase);
                bool rightInS2 = s2.Contains(p.RightTable, StringComparer.OrdinalIgnoreCase);

                if (leftInS1 && rightInS2) return p;

                bool leftInS2 = s2.Contains(p.LeftTable, StringComparer.OrdinalIgnoreCase);
                bool rightInS1 = s1.Contains(p.RightTable, StringComparer.OrdinalIgnoreCase);

                if (leftInS2 && rightInS1)
                {
                    // Transpose fields of condition symmetrically
                    return new JoinPredicate
                    {
                        LeftTable = p.RightTable,
                        LeftColumn = p.RightColumn,
                        RightTable = p.LeftTable,
                        RightColumn = p.LeftColumn,
                        Operator = p.Operator
                    };
                }
            }
            return null;
        }

        private List<IPhysicalOperator> EvaluatePhysicalJoinOptions(IPhysicalOperator left, IPhysicalOperator right, JoinPredicate pred)
        {
            var candidates = new List<IPhysicalOperator>();
            var leftMeta = _catalog.GetTable(pred.LeftTable);
            var rightMeta = _catalog.GetTable(pred.RightTable);

            // OPTION 1: Co-Located Hash Join
            // No network movements required if data is already partitioning-aligned on the same exact physical nodes.
            if (left.Distribution.IsCoLocatedWith(right.Distribution, pred.LeftColumn, pred.RightColumn))
            {
                candidates.Add(new PhysicalCoLocatedHashJoin(left, right, pred));
            }

            // OPTION 2: Broadcast Hash Join (Left to Right)
            candidates.Add(new PhysicalBroadcastHashJoin(left, right, pred, broadcastRight: false, leftMeta.RowSize, rightMeta.RowSize));

            // OPTION 3: Broadcast Hash Join (Right to Left)
            candidates.Add(new PhysicalBroadcastHashJoin(left, right, pred, broadcastRight: true, leftMeta.RowSize, rightMeta.RowSize));

            // OPTION 4: Distributed Shuffle Hash Join (Repartition both inputs using the join key hash)
            var mergedNodes = new HashSet<string>(leftMeta.Nodes.Concat(rightMeta.Nodes));
            candidates.Add(new PhysicalShuffleHashJoin(left, right, pred, leftMeta.RowSize, rightMeta.RowSize, mergedNodes));

            return candidates;
        }
    }

