            Distribution = new PhysicalDistribution(type, metadata.PartitionKey, metadata.Nodes);
            EstimatedRowCount = metadata.RowCount;
            CoveredTables = new HashSet<string>(StringComparer.OrdinalIgnoreCase) { TableName };

            double ioSeconds = metadata.RowCount * CostModel.IO_ROW_READ_COST;
            CumulativeCost = new PlanCost(network: 0, cpu: 0, io: ioSeconds);
        }

        public void Print(int indent)
