    public class PhysicalExchange : IPhysicalOperator
    {
        public IPhysicalOperator Input { get; }
        public PhysicalDistribution Distribution { get; }
        public PlanCost CumulativeCost { get; }
        public double EstimatedRowCount => Input.EstimatedRowCount;
        public HashSet<string> CoveredTables => Input.CoveredTables;

        public PhysicalExchange(IPhysicalOperator input, PhysicalDistribution targetDistribution, int rowBytesSize)
        {
            Input = input;
            Distribution = targetDistribution;

            double networkSeconds = 0;
            double numTargetNodes = targetDistribution.Nodes.Count;

            if (targetDistribution.Type == DistributionType.Broadcast)
            {
                // Multi-cast: send the full dataset to all target nodes (minus local home nodes, modeled at (N-1))
                double bytesTransferred = input.EstimatedRowCount * rowBytesSize * Math.Max(1, numTargetNodes - 1);
                networkSeconds = bytesTransferred / CostModel.NETWORK_BANDWIDTH_BYTES_PER_SEC;
            }
            else if (targetDistribution.Type == DistributionType.Hash)
            {
                // Unicast hash-based repartition shuffle network distribution overhead model: (1 - 1/N)
                double networkFraction = numTargetNodes > 1 ? (1.0 - (1.0 / numTargetNodes)) : 0.0;
                double bytesTransferred = input.EstimatedRowCount * rowBytesSize * networkFraction;
                networkSeconds = bytesTransferred / CostModel.NETWORK_BANDWIDTH_BYTES_PER_SEC;
            }

            double serializationCpuSeconds = input.EstimatedRowCount * CostModel.CPU_ROW_OP_COST * 1.5;
            CumulativeCost = input.CumulativeCost + new PlanCost(networkSeconds, serializationCpuSeconds, 0);
        }

        public void Print(int indent)
        {
            Console.WriteLine($"{new string(' ', indent)}└── [PhysicalExchange] Net Redistribution to -> {Distribution} (Net-Overhead: {CumulativeCost.NetworkCost:F5}s)");
            Input.Print(indent + 4);
        }
    }

    public class PhysicalCoLocatedHashJoin : IPhysicalOperator
    {
        public IPhysicalOperator Left { get; }
        public IPhysicalOperator Right { get; }
        public JoinPredicate Predicate { get; }
        public PhysicalDistribution Distribution => Left.Distribution;
        public PlanCost CumulativeCost { get; }
        public double EstimatedRowCount { get; }
        public HashSet<string> CoveredTables { get; }

        public PhysicalCoLocatedHashJoin(IPhysicalOperator left, IPhysicalOperator right, JoinPredicate predicate)
        {
            Left = left;
            Right = right;
            Predicate = predicate;
            CoveredTables = new HashSet<string>(left.CoveredTables.Concat(right.CoveredTables), StringComparer.OrdinalIgnoreCase);

            // Simple join selectivity modeling
            EstimatedRowCount = Math.Max(left.EstimatedRowCount, right.EstimatedRowCount) * 0.4;

            double localJoinCpuCost = (left.EstimatedRowCount + right.EstimatedRowCount) * CostModel.HASH_JOIN_CPU_FACTOR;
            CumulativeCost = left.CumulativeCost + right.CumulativeCost + new PlanCost(0, localJoinCpuCost, 0);
        }

        public void Print(int indent)
        {
            Console.WriteLine($"{new string(' ', indent)}└── [PhysicalCoLocatedHashJoin] Join: {Predicate.LeftTable}.{Predicate.LeftColumn} = {Predicate.RightTable}.{Predicate.RightColumn} (No-Network Local Fast Join)");
            Left.Print(indent + 4);
            Right.Print(indent + 4);
        }
    }

    public class PhysicalBroadcastHashJoin : IPhysicalOperator
    {
        public IPhysicalOperator Left { get; }
        public IPhysicalOperator Right { get; }
        public JoinPredicate Predicate { get; }
        public PhysicalDistribution Distribution { get; }
        public PlanCost CumulativeCost { get; }
        public double EstimatedRowCount { get; }
        public HashSet<string> CoveredTables { get; }

        public PhysicalBroadcastHashJoin(IPhysicalOperator left, IPhysicalOperator right, JoinPredicate predicate, bool broadcastRight, int leftRowBytes, int rightRowBytes)
        {
            Predicate = predicate;
            CoveredTables = new HashSet<string>(left.CoveredTables.Concat(right.CoveredTables), StringComparer.OrdinalIgnoreCase);
            EstimatedRowCount = Math.Max(left.EstimatedRowCount, right.EstimatedRowCount) * 0.4;

            double localJoinCpu = (left.EstimatedRowCount + right.EstimatedRowCount) * CostModel.HASH_JOIN_CPU_FACTOR;

            if (broadcastRight)
            {
                Distribution = left.Distribution;
                var targetDist = new PhysicalDistribution(DistributionType.Broadcast, null, left.Distribution.Nodes);
                var exchange = new PhysicalExchange(right, targetDist, rightRowBytes);

                Left = left;
                Right = exchange;
                CumulativeCost = left.CumulativeCost + exchange.CumulativeCost + new PlanCost(0, localJoinCpu, 0);
            }
            else
            {
                Distribution = right.Distribution;
                var targetDist = new PhysicalDistribution(DistributionType.Broadcast, null, right.Distribution.Nodes);
                var exchange = new PhysicalExchange(left, targetDist, leftRowBytes);

                Left = exchange;
                Right = right;
                CumulativeCost = exchange.CumulativeCost + right.CumulativeCost + new PlanCost(0, localJoinCpu, 0);
            }
        }

        public void Print(int indent)
        {
            Console.WriteLine($"{new string(' ', indent)}└── [PhysicalBroadcastHashJoin] Join: {Predicate.LeftTable}.{Predicate.LeftColumn} = {Predicate.RightTable}.{Predicate.RightColumn}");
            Left.Print(indent + 4);
            Right.Print(indent + 4);
        }
    }

    public class PhysicalShuffleHashJoin : IPhysicalOperator
    {
        public IPhysicalOperator Left { get; }
        public IPhysicalOperator Right { get; }
        public JoinPredicate Predicate { get; }
        public PhysicalDistribution Distribution { get; }
        public PlanCost CumulativeCost { get; }
        public double EstimatedRowCount { get; }
        public HashSet<string> CoveredTables { get; }

        public PhysicalShuffleHashJoin(IPhysicalOperator left, IPhysicalOperator right, JoinPredicate predicate, int leftRowBytes, int rightRowBytes, HashSet<string> clusterNodes)
        {
            Predicate = predicate;
            CoveredTables = new HashSet<string>(left.CoveredTables.Concat(right.CoveredTables), StringComparer.OrdinalIgnoreCase);
            EstimatedRowCount = Math.Max(left.EstimatedRowCount, right.EstimatedRowCount) * 0.4;

            var targetLeftDist = new PhysicalDistribution(DistributionType.Hash, predicate.LeftColumn, clusterNodes);
            var targetRightDist = new PhysicalDistribution(DistributionType.Hash, predicate.RightColumn, clusterNodes);

            var exLeft = new PhysicalExchange(left, targetLeftDist, leftRowBytes);
            var exRight = new PhysicalExchange(right, targetRightDist, rightRowBytes);

            Left = exLeft;
            Right = exRight;
            Distribution = targetLeftDist;

            double localJoinCpu = (left.EstimatedRowCount + right.EstimatedRowCount) * CostModel.HASH_JOIN_CPU_FACTOR;
            CumulativeCost = exLeft.CumulativeCost + exRight.CumulativeCost + new PlanCost(0, localJoinCpu, 0);
        }

        public void Print(int indent)
        {
            Console.WriteLine($"{new string(' ', indent)}└── [PhysicalShuffleHashJoin] Join: {Predicate.LeftTable}.{Predicate.LeftColumn} = {Predicate.RightTable}.{Predicate.RightColumn} (Double-Sided Shuffling)");
            Left.Print(indent + 4);
            Right.Print(indent + 4);
        }
    }

